<?php

declare(strict_types=1);

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * @property int $id
 * @property string $conversation_id
 * @property string $direction `in|out`
 * @property string $sender_type `customer|staff|system`
 * @property string|null $sender_name
 * @property string|null $external_message_id
 * @property string|null $client_token
 * @property string $body
 * @property string|null $attachment_path path on the private `local` disk, generated by the server
 * @property string|null $attachment_mime `image/jpeg|png|gif|webp`
 * @property int|null $attachment_size bytes
 * @property int|null $attachment_width
 * @property int|null $attachment_height
 * @property string|null $attachment_name
 * @property string|null $attachment_mxc `mxc://` of a voice message, relayed on demand instead of stored
 * @property string|null $send_status `sending|sent|unknown|failed`, only for outbound messages
 * @property string|null $error
 * @property Carbon|null $sent_at
 */
class ChatMessage extends Model
{
    // * Private disk holding inbound attachments and profile pictures; never served by path, only through the permission-checked routes.
    public const ATTACHMENT_DISK = 'local';

    public const DIRECTION_IN = 'in';

    public const DIRECTION_OUT = 'out';

    public const SENDER_CUSTOMER = 'customer';

    public const SENDER_STAFF = 'staff';

    public const SENDER_SYSTEM = 'system';

    public const STATUS_SENDING = 'sending';

    public const STATUS_SENT = 'sent';

    // * Timeout or ambiguous failure: the provider may or may not have delivered it. Never retried automatically.
    public const STATUS_UNKNOWN = 'unknown';

    public const STATUS_FAILED = 'failed';

    // * Plain text limit of the Telegram `sendMessage` method.
    public const MAX_BODY_LENGTH = 4096;

    protected $fillable = [
        'conversation_id',
        'direction',
        'sender_type',
        'sender_name',
        'external_message_id',
        'client_token',
        'body',
        'attachment_path',
        'attachment_mime',
        'attachment_size',
        'attachment_width',
        'attachment_height',
        'attachment_name',
        'attachment_mxc',
        'send_status',
        'error',
        'sent_at',
    ];

    protected $casts = [
        'sent_at' => 'datetime',
        'attachment_size' => 'integer',
        'attachment_width' => 'integer',
        'attachment_height' => 'integer',
    ];

    /** @return BelongsTo<Conversation, $this> */
    public function conversation(): BelongsTo
    {
        return $this->belongsTo(Conversation::class);
    }
}
